SELECT CASE WHEN sqft >= 15463 THEN 'PREMIUM' ELSE 'STANDARD' END AS sqft_tier, DATE_TRUNC('MONTH', opened_date) AS activity_month, BIT_OR(sqft) AS sqft_bit_or, SORT_ARRAY(COLLECT_SET(region)) AS region_list, APPROX_PERCENTILE(sqft, ARRAY(0.25, 0.5, 0.75)) AS sqft_quartiles, GROUPING(CASE WHEN sqft >= 15463 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM stores GROUP BY GROUPING SETS ((CASE WHEN sqft >= 15463 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('MONTH', opened_date)), (CASE WHEN sqft >= 15463 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) ORDER BY sqft_bit_or DESC NULLS FIRST;
